INSERT INTO public.report_card VALUES (63, '2026-05-27 17:41:28.141572+00', '2026-05-27 17:45:09.369298+00', 'Total de reseñas por año', NULL, 'line', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    EXTRACT(YEAR FROM review_date)          AS \"Año\",\n    COUNT(*)                                AS \"Total Reseñas\",\n    ROUND(AVG(rating_overall), 1)           AS \"Rating Promedio\",\n    COUNT(DISTINCT id_hostel)               AS \"Hostels con Actividad\"\nFROM stg_reviews\nWHERE review_date IS NOT NULL\n  AND rating_overall IS NOT NULL\n  AND EXTRACT(YEAR FROM review_date) BETWEEN 2010 AND 2024\nGROUP BY 1\nORDER BY 1;"}]}', '{"series_settings":{"Total Reseñas":{"color":"#51528D"}},"graph.dimensions":["Año"],"graph.metrics":["Total Reseñas"],"graph.series_order_dimension":null,"graph.series_order":null,"graph.label_value_formatting":"auto","graph.x_axis.scale":"linear"}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"numeric","semantic_type":null,"lib/deduplicated-name":"Año","lib/original-name":"Año","name":"Año","lib/source":"source/native","lib/source-column-alias":"Año","source":"native","field_ref":["field","Año",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"Año","display_name":"Año","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Number":{"skewness":0.0,"min":2021.0,"q1":2021.0,"q3":2023.0,"excess-kurtosis":-1.200000000000001,"zero-fraction":0.0,"mode-fraction":0.25,"top-3-fraction":0.75,"max":2024.0,"sd":1.2909944487358056,"avg":2022.5}}},"base_type":"type/Decimal"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"Total Reseñas","lib/original-name":"Total Reseñas","name":"Total Reseñas","lib/source":"source/native","lib/source-column-alias":"Total Reseñas","source":"native","field_ref":["field","Total Reseñas",{"base-type":"type/BigInteger"}],"effective_type":"type/BigInteger","lib/desired-column-alias":"Total Reseñas","display_name":"Total Reseñas","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Number":{"skewness":-0.047035816514701914,"min":33657.0,"q1":33657.0,"q3":356827.0,"excess-kurtosis":-4.425190921807729,"zero-fraction":0.0,"mode-fraction":0.25,"top-3-fraction":0.75,"max":426908.0,"sd":188152.9037396624,"avg":233513.5}}},"base_type":"type/BigInteger"},{"database_type":"numeric","semantic_type":"type/Score","lib/deduplicated-name":"Rating Promedio","lib/original-name":"Rating Promedio","name":"Rating Promedio","lib/source":"source/native","lib/source-column-alias":"Rating Promedio","source":"native","field_ref":["field","Rating Promedio",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"Rating Promedio","display_name":"Rating Promedio","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Number":{"skewness":0.4366620845757565,"min":86.9,"q1":86.9,"q3":87.7,"excess-kurtosis":1.1656663364605357,"zero-fraction":0.0,"mode-fraction":0.25,"top-3-fraction":0.75,"max":88.5,"sd":0.6608075867199624,"avg":87.65}}},"base_type":"type/Decimal"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"Hostels con Actividad","lib/original-name":"Hostels con Actividad","name":"Hostels con Actividad","lib/source":"source/native","lib/source-column-alias":"Hostels con Actividad","source":"native","field_ref":["field","Hostels con Actividad",{"base-type":"type/BigInteger"}],"effective_type":"type/BigInteger","lib/desired-column-alias":"Hostels con Actividad","display_name":"Hostels con Actividad","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Number":{"skewness":0.23975825615363833,"min":6049.0,"q1":6049.0,"q3":10231.0,"excess-kurtosis":-3.848888051894976,"zero-fraction":0.0,"mode-fraction":0.25,"top-3-fraction":0.75,"max":11933.0,"sd":2778.292701162592,"avg":8770.5}}},"base_type":"type/BigInteger"}]', NULL, 'n9R_4B5fwzZ60T1TnULyW', '[]'