INSERT INTO public.report_card VALUES (49, '2026-05-21 23:41:09.329548+00', '2026-05-21 23:41:09.329548+00', '[3C] Grupos equivalentes válidos por tipo y estrellas (tabla resumen)', NULL, 'table', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    hostel_type                     AS \"Tipo\",\n    star_rating                     AS \"Estrellas\",\n    COUNT(*)                        AS \"Grupos\",\n    SUM(hostel_count)               AS \"Hostels\",\n    SUM(review_count)               AS \"Reseñas\",\n    ROUND(AVG(avg_overall_group),2) AS \"Rating Promedio\"\nFROM kpi_equivalent_groups\nWHERE is_valid = TRUE AND group_level = ''city''\nGROUP BY hostel_type, star_rating\nORDER BY hostel_type, star_rating;\n "}]}', '{"table.pivot_column":"Rating Promedio","table.cell_column":"Estrellas"}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Tipo","lib/original-name":"Tipo","name":"Tipo","lib/source":"source/native","lib/source-column-alias":"Tipo","source":"native","field_ref":["field","Tipo",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Tipo","display_name":"Tipo","fingerprint":{"global":{"distinct-count":5,"nil%":0.0},"type":{"type/Text":{"max-length":10.0,"min-length":5.0,"percent-email":0.0,"percent-state":0.0,"average-length":7.176470588235294,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.29411764705882354,"top-3-fraction":0.8823529411764706,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"int4","semantic_type":null,"lib/deduplicated-name":"Estrellas","lib/original-name":"Estrellas","name":"Estrellas","lib/source":"source/native","lib/source-column-alias":"Estrellas","source":"native","field_ref":["field","Estrellas",{"base-type":"type/Integer"}],"effective_type":"type/Integer","lib/desired-column-alias":"Estrellas","display_name":"Estrellas","fingerprint":{"gl