INSERT INTO public.report_card VALUES (50, '2026-05-21 23:41:29.432306+00', '2026-05-21 23:41:29.432306+00', '[3D] Correlación volumen vs rating por grupo (scatter — top grupos con más hostels)', NULL, 'table', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    g.location                      AS \"Ubicación\",\n    g.hostel_type                   AS \"Tipo\",\n    g.star_rating                   AS \"Estrellas\",\n    g.hostel_count                  AS \"Cantidad Hostels\",\n    g.avg_overall_group             AS \"Rating Promedio Grupo\",\n    v.pearson_r                     AS \"Correlación Volumen-Rating\"\nFROM kpi_volume_vs_rating v\nJOIN kpi_equivalent_groups g ON v.group_key = g.group_key\nWHERE g.is_valid = TRUE\nORDER BY g.hostel_count DESC\nLIMIT 30;"}]}', '{"table.pivot_column":"Tipo","table.cell_column":"Estrellas"}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"Ubicación","lib/original-name":"Ubicación","name":"Ubicación","lib/source":"source/native","lib/source-column-alias":"Ubicación","source":"native","field_ref":["field","Ubicación",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Ubicación","display_name":"Ubicación","fingerprint":{"global":{"distinct-count":30,"nil%":0.0},"type":{"type/Text":{"max-length":16.0,"min-length":3.0,"percent-email":0.0,"percent-state":0.0,"average-length":7.6,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.03333333333333333,"top-3-fraction":0.1,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Tipo","lib/original-name":"Tipo","name":"Tipo","lib/source":"source/native","lib/source-column-alias":"Tipo","source":"native","field_ref":["field","Tipo",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Tipo","display_name":"Tipo","fingerpri