INSERT INTO public.report_card VALUES (62, '2026-05-27 17:02:39.653476+00', '2026-05-27 17:02:39.653476+00', 'Tipo de alojamiento por rango etario (OK)', NULL, 'row', '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n    u.age_range                             AS \"Rango Etario\",\n    h.type                                  AS \"Tipo de Alojamiento\",\n    COUNT(r.id_review)                      AS \"Total Reseñas\",\n    ROUND(AVG(r.rating_overall), 1)         AS \"Rating Promedio\",\n    ROUND(COUNT(r.id_review) * 100.0\n          / SUM(COUNT(r.id_review)) OVER (PARTITION BY u.age_range), 1)\n                                            AS \"% dentro del Rango Etario\"\nFROM stg_reviews r\nJOIN stg_users u ON r.id_user = u.id_user\nJOIN stg_hostels h ON r.id_hostel = h.id_hostel\nWHERE u.age_range IS NOT NULL\n  AND r.rating_overall IS NOT NULL\n  AND h.type IN (''HOSTEL'', ''GUESTHOUSE'', ''HOTEL'')\nGROUP BY u.age_range, h.type\nHAVING COUNT(r.id_review) >= 100\nORDER BY u.age_range, COUNT(r.id_review) DESC;","lib/type":"mbql.stage/native"}]}', '{"graph.series_order":null,"graph.series_order_dimension":null,"graph.metrics":["Total Reseñas"],"graph.dimensions":["Tipo de Alojamiento","Rango Etario"],"series_settings":{"41+":{"color":"#98D9D9"},"31-40":{"color":"#EF8C8C"},"18-24":{"color":"#227FD2"},"25-30":{"color":"#F9D45C"}}}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Rango Etario","lib/original-name":"Rango Etario","name":"Rango Etario","lib/source":"source/native","lib/source-column-alias":"Rango Etario","source":"native","field_ref":["field","Rango Etario",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Rango Etario","display_name":"Rango Etario","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Text":{"max-length":5.0,"min-length":3.0,"percent-email":0.0,"percent-state":0.0,"average-leng