INSERT INTO public.report_card VALUES (55, '2026-05-26 19:04:53.024407+00', '2026-05-26 19:04:53.024407+00', 'Top 15 ciudades con mas hostels', NULL, 'table', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    city_name             AS \"Ciudad\",\n    city_country          AS \"País\",\n    COUNT(*)              AS \"Hostels\"\nFROM stg_hostels\nGROUP BY city_name, city_country\nORDER BY COUNT(*) DESC\nLIMIT 15;"}]}', '{"table.pivot_column":"País","table.cell_column":"Hostels"}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"Ciudad","lib/original-name":"Ciudad","name":"Ciudad","lib/source":"source/native","lib/source-column-alias":"Ciudad","source":"native","field_ref":["field","Ciudad",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Ciudad","display_name":"Ciudad","fingerprint":{"global":{"distinct-count":15,"nil%":0.0},"type":{"type/Text":{"max-length":10.0,"min-length":4.0,"percent-email":0.0,"percent-state":0.0,"average-length":6.8,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.06666666666666667,"top-3-fraction":0.2,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"País","lib/original-name":"País","name":"País","lib/source":"source/native","lib/source-column-alias":"País","source":"native","field_ref":["field","País",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"País","display_name":"País","fingerprint":{"global":{"distinct-count":11,"nil%":0.0},"type":{"type/Text":{"max-length":8.0,"min-length":4.0,"percent-email":0.0,"percent-state":0.0,"average-length":6.133333333333334,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.2,"top-3-fraction":0.4666666666666667,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-