INSERT INTO public.report_card VALUES (48, '2026-05-21 23:40:45.705705+00', '2026-05-26 18:40:50.283186+00', '[3B] Distribución de desvíos respecto al grupo (histograma)', NULL, 'table', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    CASE\n        WHEN deviation_from_group < -10 THEN ''Muy por debajo (-10 o menos)''\n        WHEN deviation_from_group < -5  THEN ''Por debajo (-10 a -5)''\n        WHEN deviation_from_group < 0   THEN ''Levemente por debajo (-5 a 0)''\n        WHEN deviation_from_group = 0   THEN ''En la media''\n        WHEN deviation_from_group <= 5  THEN ''Levemente por encima (0 a 5)''\n        WHEN deviation_from_group <= 10 THEN ''Por encima (5 a 10)''\n        ELSE ''Muy por encima (+10 o más)''\n    END                             AS \"Posición relativa\",\n    COUNT(*)                        AS \"Cantidad de Hostels\"\nFROM kpi_hostel_ranking\nGROUP BY 1\nORDER BY MIN(deviation_from_group);"}]}', '{"table.pivot_column":"Cantidad de Hostels","table.cell_column":"Posición relativa"}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"Posición relativa","lib/original-name":"Posición relativa","name":"Posición relativa","lib/source":"source/native","lib/source-column-alias":"Posición relativa","source":"native","field_ref":["field","Posición relativa",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Posición relativa","display_name":"Posición relativa","fingerprint":{"global":{"distinct-count":7,"nil%":0.0},"type":{"type/Text":{"max-length":29.0,"min-length":11.0,"percent-email":0.0,"percent-state":0.0,"average-length":23.142857142857142,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.14285714285714285,"top-3-fraction":0.42857142857142855,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"Cantidad d