INSERT INTO public.report_card VALUES (60, '2026-05-26 20:05:38.808483+00', '2026-05-26 20:05:38.808483+00', 'Volumen de reseñas por perfil de viajero', 'Qué segmento genera más actividad en la plataforma, qué combinación de tipo de viaje + género genera más reseñas. Útil para saber dónde concentrar presupuesto publicitario.', 'bar', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    u.trip_code                             AS \"Tipo de Viaje\",\n    u.gender_code                           AS \"Género\",\n    COUNT(r.id_review)                      AS \"Total Reseñas\",\n    ROUND(AVG(r.rating_overall), 1)         AS \"Rating Promedio\",\n    ROUND(COUNT(r.id_review) * 100.0\n          / SUM(COUNT(r.id_review)) OVER (), 1) AS \"% del Total de Reseñas\"\nFROM stg_reviews r\nJOIN stg_users u ON r.id_user = u.id_user\nWHERE u.trip_code IS NOT NULL\n  AND u.gender_code IS NOT NULL\n  AND r.rating_overall IS NOT NULL\nGROUP BY u.trip_code, u.gender_code\nORDER BY COUNT(r.id_review) DESC;"}]}', '{"graph.x_axis.scale":"ordinal","graph.dimensions":["Tipo de Viaje","Género"],"graph.metrics":["Total Reseñas","Rating Promedio","% del Total de Reseñas"]}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Tipo de Viaje","lib/original-name":"Tipo de Viaje","name":"Tipo de Viaje","lib/source":"source/native","lib/source-column-alias":"Tipo de Viaje","source":"native","field_ref":["field","Tipo de Viaje",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Tipo de Viaje","display_name":"Tipo de Viaje","fingerprint":{"global":{"distinct-count":6,"nil%":0.0},"type":{"type/Text":{"max-length":15.0,"min-length":5.0,"percent-email":0.0,"percent-state":0.0,"average-length":9.5,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.16666666666666666,"top-3-fraction":0.5,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Género","lib/original-name":"Género","name":"Género","lib/source":"source/native","lib/source-column-alias":"Género","source":"native","field_ref":["field","Género",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Género","display_name":"Género","fingerprint":{"global":{"distinct-count":6,"nil%":0.0},"type":{"type/Text":{"max-length":14.0,"min-length":4.0,"percent-email":0.0,"percent-state":0.0,"average-length":8.666666666666666,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.16666666666666666,"top-3-fraction":0.5,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"Total Reseñas","lib/original-name":"Total Reseñas","name":"Total Reseñas","lib/source":"source/native","lib/source-column-alias":"Total Reseñas","source":"native","field_ref":["field","Total Reseñas",{"base-type":"type/BigInteger"}],"effective_type":"type/BigInteger","lib/desired-column-alias":"Total Reseñas","display_name":"Total Reseñas","fingerprint":{"global":{"distinct-count":36,"nil%":0.0},"type":{"type/Number":{"skewness":1.97459698454726,"min":538.0,"q1":1749.0,"q3":41225.0,"excess-kurtosis":3.8045778988107184,"zero-fraction":0.0,"mode-fraction":0.027777777777777776,"top-3-fraction":0.08333333333333333,"max":153337.0,"sd":38837.7355025786,"avg":25945.94444444445}}},"base_type":"type/BigInteger"},{"database_type":"numeric","semantic_type":"type/Score","lib/deduplicated-name":"Rating Promedio","lib/original-name":"Rating Promedio","name":"Rating Promedio","lib/source":"source/native","lib/source-column-alias":"Rating Promedio","source":"native","field_ref":["field","Rating Promedio",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"Rating Promedio","display_name":"Rating Promedio","fingerprint":{"global":{"distinct-count":29,"nil%":0.0},"type":{"type/Number":{"skewness":-1.075419508