INSERT INTO public.report_card VALUES (59, '2026-05-26 19:59:40.493683+00', '2026-05-26 19:59:40.493683+00', 'Distribución de hostels por banda de calidad', 'Bandas de calidad → cuántos hostels caen en cada nivel (≥90, ≥80, etc.).', 'pie', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    CASE\n        WHEN avg_overall >= 90 THEN '' Excelente (90-100)''\n        WHEN avg_overall >= 80 THEN '' Muy bueno (80-89)''\n        WHEN avg_overall >= 70 THEN '' Bueno (70-79)''\n        WHEN avg_overall >= 60 THEN '' Regular (60-69)''\n        ELSE ''Por debajo (< 60)''\n    END                                     AS \"Banda de Calidad\",\n    COUNT(*)                                AS \"Cantidad de Hostels\",\n    ROUND(AVG(avg_overall), 1)              AS \"Rating Promedio de la Banda\",\n    ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 1) AS \"% del Total\"\nFROM kpi_hostel_ratings\nGROUP BY 1\nORDER BY MIN(avg_overall) DESC;"}]}', '{}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"Banda de Calidad","lib/original-name":"Banda de Calidad","name":"Banda de Calidad","lib/source":"source/native","lib/source-column-alias":"Banda de Calidad","source":"native","field_ref":["field","Banda de Calidad",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Banda de Calidad","display_name":"Banda de Calidad","fingerprint":{"global":{"distinct-count":5,"nil%":0.0},"type":{"type/Text":{"max-length":19.0,"min-length":14.0,"percent-email":0.0,"percent-state":0.0,"average-length":16.8,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.2,"top-3-fraction":0.6,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"Cantidad de Hostels","lib/original-name":"Cantidad de Hostels","name":"Cantidad de Hostels","lib/source":"source/native","lib/source-column-