INSERT INTO public.report_card VALUES (64, '2026-05-27 17:44:07.577205+00', '2026-05-27 17:44:07.577205+00', 'Total de hostels activos por año', NULL, 'line', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n    EXTRACT(YEAR FROM review_date)          AS \"Año\",\n    COUNT(*)                                AS \"Total Reseñas\",\n    ROUND(AVG(rating_overall), 1)           AS \"Rating Promedio\",\n    COUNT(DISTINCT id_hostel)               AS \"Hostels con Actividad\"\nFROM stg_reviews\nWHERE review_date IS NOT NULL\n  AND rating_overall IS NOT NULL\n  AND EXTRACT(YEAR FROM review_date) BETWEEN 2010 AND 2024\nGROUP BY 1\nORDER BY 1;"}]}', '{"series_settings":{"Total Reseñas":{"color":"#51528D"}},"graph.dimensions":["Año"],"graph.series_order_dimension":null,"graph.series_order":null,"graph.label_value_formatting":"auto","graph.x_axis.scale":"linear","graph.metrics":["Hostels con Actividad"]}', 1, 2, NULL, 'native', false, NULL, NULL, NULL, false, NULL, NULL, '[{"database_type":"numeric","semantic_type":null,"lib/deduplicated-name":"Año","lib/original-name":"Año","name":"Año","lib/source":"source/native","lib/source-column-alias":"Año","source":"native","field_ref":["field","Año",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"Año","display_name":"Año","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Number":{"skewness":0.0,"min":2021.0,"q1":2021.0,"q3":2023.0,"excess-kurtosis":-1.200000000000001,"zero-fraction":0.0,"mode-fraction":0.25,"top-3-fraction":0.75,"max":2024.0,"sd":1.2909944487358056,"avg":2022.5}}},"base_type":"type/Decimal"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"Total Reseñas","lib/original-name":"Total Reseñas","name":"Total Reseñas","lib/source":"source/native","lib/source-column-alias":"Total Reseñas","source":"native","field_ref":["field","Total Reseñas",{"base-type":"type/BigInteger"}],"effective_type":"ty